/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    tickCcTimers, isStunned, isPoisoned, isSlowedByShockwave, titanShockAttackSpeedDivider, titanShockMassFactor, computeBotPlusBenefit, resolveTitanShockAttackSpeedSlow (+3 more)
 * depends    src/mechanics/combat/types
 * used by    src/calculators/specs.generated, src/mechanics/combat/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { EnemyCcTimers } from './types'

export function tickCcTimers(timers: EnemyCcTimers, deltaTime: number): EnemyCcTimers {
  return {
    ...timers,
    stunTime: Math.max(0, timers.stunTime - deltaTime),
    poisonTime: Math.max(0, timers.poisonTime - deltaTime),
    lingerTime: Math.max(0, timers.lingerTime - deltaTime),
    fearedTime: Math.max(0, timers.fearedTime - deltaTime),
    blackHoleTime: Math.max(0, timers.blackHoleTime - deltaTime),
    shockwaveTime: Math.max(0, timers.shockwaveTime - deltaTime),
  }
}

export function isStunned(timers: EnemyCcTimers): boolean {
  return timers.stunTime > 0
}

export function isPoisoned(timers: EnemyCcTimers): boolean {
  return timers.poisonTime > 0 || timers.poisonCount > 0
}

export function isSlowedByShockwave(timers: EnemyCcTimers): boolean {
  return timers.shockwaveTime > 0
}

export function titanShockAttackSpeedDivider(
  currentDivider: number,
  ccDuration: number,
  titanSlowFactor: number,
): number {
  const base = Math.max(ccDuration, 1)
  const tier = Math.floor(base)
  const stack = tier + 1
  const slow = titanSlowFactor * stack + 1
  return currentDivider * slow
}

/* * Clamp `enemyMassOnActivate` to min 1.0, then `log10`, then add 1.
 * Multiplied by `titan shock attack speed slow()`.
 */
export function titanShockMassFactor(enemyMassOnActivate: number): number {
  return Math.log10(Math.max(enemyMassOnActivate, 1)) + 1
}

/**
 * Bot+ benefit at a level: base benefit plus the per-level benefit times the level.
 * The base and per-level values come from the versioned Bot+ catalog.
 */
export function computeBotPlusBenefit(
  plusBaseBenefit: number,
  plusBenefitPerLevel: number,
  level: number,
): number {
  return plusBaseBenefit + plusBenefitPerLevel * level
}

/** Current Bot+ benefits are indexed by bot type (Flame=0 through Bot=4):
 * - index 1: Thunder Bot+ Titan Shock current value
 * - index 4: Bot Bot+ Maximum Power current value
 *
 * Titan Shock level ladder is defined by the versioned model (`BOT_PLUS_*_V29` index 1 =
 * `0.05 + 0.01 * level`). Callers may still pass a live `plusBenefit` snapshot.
 */
export function resolveTitanShockAttackSpeedSlow(
  plusBenefit: readonly number[],
  boostedTitanShocked: boolean,
  titanShocked = true,
): number {
  if (boostedTitanShocked) {
    if (plusBenefit.length <= 4) return 1
    return plusBenefit[1]! * plusBenefit[4]!
  }
  if (titanShocked) {
    if (plusBenefit.length < 2) return 1
    return plusBenefit[1]!
  }
  return 1
}

/** `titan shock reduction` when AttackSpeedSlow is supplied by the caller. */
export function titanShockReduction(
  enemyMassOnActivate: number,
  attackSpeedSlow: number,
): number {
  return titanShockMassFactor(enemyMassOnActivate) * attackSpeedSlow
}

/**
 * `ApplyTitanShock` cooldown multiply when shocked flags are set:
 * `atkCooldown *= (reduction + 1)`.
 */
export function applyTitanShockAttackCooldown(
  atkCooldown: number,
  enemyMassOnActivate: number,
  attackSpeedSlow: number,
): number {
  return atkCooldown * (titanShockReduction(enemyMassOnActivate, attackSpeedSlow) + 1)
}

export const CC_TIMER_FIELDS = [
  'stunTime',
  'poisonTime',
  'poisonCount',
  'lingerTime',
  'fearedTime',
  'blackHoleTime',
  'shockwaveTime',
] as const
